DO $patch$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.submit_site_report(uuid)'::regprocedure); IF position('sum(q.today_qty)' IN d)=0 THEN RAISE EXCEPTION 'Progress alias anchor missing'; END IF; d:=replace(d,'sum(q.today_qty)','sum(srq.today_qty)'); d:=replace(d,'public.site_report_quantities q JOIN public.daily_measurements dm ON dm.id=q.report_id WHERE q.boq_item_id=b.id','public.site_report_quantities srq JOIN public.daily_measurements dm ON dm.id=srq.report_id WHERE srq.boq_item_id=b.id'); EXECUTE d; END $patch$;